def run_with_live_log(command, cwd, env, logfile):
    with logfile.open('w',encoding='utf-8') as log:
        proc=subprocess.Popen(command,cwd=cwd,env=env,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,encoding='utf-8',errors='replace',bufsize=1)
        try:
            for line in proc.stdout:
                print(line,end='',flush=True)
                try:log.write(line);log.flush()
                except OSError as exc:print('LOG_WRITE_FAILED',repr(exc),flush=True)
            return proc.wait()
        finally:
            if proc.poll() is None:
                proc.terminate()
                try:proc.wait(timeout=10)
                except subprocess.TimeoutExpired:proc.kill();proc.wait()
            proc.stdout.close()

